import vuedraggable from 'vuedraggable';
import storeLabelList from "@/components/storeLabelList";
import goodsList from '@/components/goodsList';
import uploadPictures from '@/components/uploadPictures';
import { brandList, cascaderListApi } from "@/api/product";
export default {
  name: 'c_promotion',
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    },
    index: {
      type: null
    }
  },
  components: {
    draggable: vuedraggable,
    storeLabelList: storeLabelList,
    goodsList: goodsList,
    uploadPictures: uploadPictures
  },
  data: function data() {
    return {
      props: {
        emitPath: false,
        multiple: true
      },
      defaults: {},
      configData: {},
      itemObj: {},
      storeLabelShow: false,
      modals: false,
      modalPic: false,
      isChoice: '单选',
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12
      },
      typeList: [{
        activeValue: 1,
        title: '指定商品'
      }, {
        activeValue: 2,
        title: '指定品牌'
      }, {
        activeValue: 3,
        title: '指定分类'
      }, {
        activeValue: 4,
        title: '商品标签'
      }],
      brandData: [],
      treeSelect: [],
      tabIndex: 1
    };
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      _this.defaults = _this.configObj;
      _this.configData = _this.configObj[_this.configNme];
      _this.getBrandList();
      _this.goodsCategory();
    });
  },
  watch: {
    configObj: {
      handler: function handler(nVal, oVal) {
        this.defaults = nVal;
        this.configData = nVal[this.configNme];
        this.tabIndex = nVal.styleConfig.tabVal;
      },
      deep: true
    }
  },
  methods: {
    // 点击图文封面
    modalPicTap: function modalPicTap(title) {
      this.modalPic = true;
    },
    bindPicDelete: function bindPicDelete() {
      this.configData.list[this.configData.tabCur].image = '';
    },
    // 获取图片信息
    getPic: function getPic(pc) {
      var _this2 = this;
      this.$nextTick(function () {
        _this2.configData.list[_this2.configData.tabCur].image = pc.att_dir;
        _this2.modalPic = false;
      });
    },
    getBrandList: function getBrandList() {
      var _this3 = this;
      brandList().then(function (res) {
        _this3.brandData = res.data;
      })["catch"](function (err) {
        _this3.$Message.error(err.msg);
      });
    },
    goodsCategory: function goodsCategory() {
      var _this4 = this;
      cascaderListApi(1).then(function (res) {
        _this4.treeSelect = res.data;
      })["catch"](function (res) {
        _this4.$Message.error(res.msg);
      });
    },
    openGoods: function openGoods() {
      this.modals = true;
    },
    //对象数组去重；
    unique: function unique(arr) {
      var res = new Map();
      return arr.filter(function (arr) {
        return !res.has(arr.id) && res.set(arr.id, 1);
      });
    },
    getProductId: function getProductId(data) {
      this.modals = false;
      var list = this.configData.list[this.configData.tabCur].goodsList.list.concat(data);
      this.configData.list[this.configData.tabCur].goodsList.list = this.unique(list);
    },
    cancel: function cancel() {
      this.modals = false;
    },
    bindGoodDelete: function bindGoodDelete(index) {
      this.configData.list[this.configData.tabCur].goodsList.list.splice(index, 1);
    },
    openStoreLabel: function openStoreLabel(row, index) {
      this.storeLabelShow = true;
      this.$refs.storeLabel.storeLabel(JSON.parse(JSON.stringify(row)));
    },
    closeStoreLabel: function closeStoreLabel(label) {
      var list = this.configData.list[this.configData.tabCur].goodsLabel.list;
      var index = list.indexOf(list.filter(function (d) {
        return d.id == label.id;
      })[0]);
      list.splice(index, 1);
      this.getLabelId(list);
    },
    activeStoreData: function activeStoreData(storeDataLabel) {
      this.storeLabelShow = false;
      this.configData.list[this.configData.tabCur].goodsLabel.list = storeDataLabel;
      this.getLabelId(storeDataLabel);
    },
    getLabelId: function getLabelId(storeDataLabel) {
      var storeActiveIds = [];
      storeDataLabel.forEach(function (item) {
        storeActiveIds.push(item.id);
      });
      this.configData.list[this.configData.tabCur].goodsLabel.activeValue = storeActiveIds;
      this.$emit('getConfig', {
        name: 'goodsLabel'
      });
    },
    // 标签弹窗关闭
    storeLabelClose: function storeLabelClose() {
      this.storeLabelShow = false;
    },
    addHotTxt: function addHotTxt() {
      if (this.configData.list.length == 0) {
        var storage = window.localStorage;
        this.itemObj = JSON.parse(storage.getItem('itemObj'));
        if (this.itemObj.link) {
          this.itemObj.link.activeVal = 0;
        }
        this.itemObj.chiild[0].val = '首发新品';
        this.itemObj.chiild[1].val = '最新出炉';
        this.itemObj.tabVal = 0;
        this.itemObj.selectConfig.activeValue = [];
        this.itemObj.goodsLabel.activeValue = [];
        this.itemObj.goodsLabel.list = [];
        this.itemObj.goodsSort = 0;
        this.itemObj.numConfig.val = 6;
        this.itemObj.goodsList.list = [];
        this.itemObj.productList.list = [];
        this.configData.list.push(this.itemObj);
      } else {
        var obj = JSON.parse(JSON.stringify(this.configData.list[this.configData.list.length - 1]));
        if (obj.chiild[0].empty) {
          obj.chiild[0].val = '';
          obj.chiild[1].val = '';
        }
        obj.tabVal = 0;
        obj.selectConfig.activeValue = [];
        obj.goodsLabel.activeValue = [];
        obj.goodsLabel.list = [];
        obj.goodsSort = 0;
        obj.numConfig.val = 6;
        obj.goodsList.list = [];
        obj.productList.list = [];
        this.configData.list.push(obj);
      }
    },
    // 删除数组
    bindDelete: function bindDelete(index) {
      if (this.configData.list.length == 1) {
        var itemObj = this.configData.list[0];
        this.itemObj = itemObj;
        var storage = window.localStorage;
        storage.setItem('itemObj', JSON.stringify(itemObj));
      }
      this.configData.list.splice(index, 1);
      this.configData.tabCur = 0;
      this.$emit('getConfig', {
        name: 'delete',
        indexs: 0
      });
    },
    activeBtn: function activeBtn(index) {
      this.configData.tabCur = index;
      // this.$emit('getConfig', { name: 'product', indexs: index })
    },
    radioChange: function radioChange(e) {
      this.$emit('getConfig', {
        name: 'promotion',
        values: e
      });
    },
    // 品牌
    brandChange: function brandChange() {
      this.$emit('getConfig', {
        name: 'brands'
      });
    },
    //商品分类
    sliderChange: function sliderChange(e) {
      this.configData.list[this.configData.tabCur].selectConfig.activeValue = e;
      this.$emit('getConfig', {
        name: 'cascader',
        values: e
      });
    },
    tabChange: function tabChange(e) {
      this.$emit('getConfig', e);
    }
  }
};
